// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAuthConfig Which sign-in options this server offers
	// (GET /auth/config)
	GetAuthConfig(ctx context.Context, request GetAuthConfigRequestObject) (GetAuthConfigResponseObject, error)
	// SignInDev Development-only sign-in by name (disabled unless DEV_LOGIN=1)
	// (POST /auth/dev)
	SignInDev(ctx context.Context, request SignInDevRequestObject) (SignInDevResponseObject, error)
	// SignInWithGoogle Sign in with a Google ID token (creates the account on first sign-in)
	// (POST /auth/google)
	SignInWithGoogle(ctx context.Context, request SignInWithGoogleRequestObject) (SignInWithGoogleResponseObject, error)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ListCards The signed-in player's collection (paged, filterable)
	// (GET /cards)
	ListCards(ctx context.Context, request ListCardsRequestObject) (ListCardsResponseObject, error)
	// OpenGifts Open your waiting partner gifts and tournament prizes
	// (POST /gifts/open)
	OpenGifts(ctx context.Context, request OpenGiftsRequestObject) (OpenGiftsResponseObject, error)
	// GetHealth Liveness and database check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetAllTimeLeaderboard All-time standings
	// (GET /leaderboard/all-time)
	GetAllTimeLeaderboard(ctx context.Context, request GetAllTimeLeaderboardRequestObject) (GetAllTimeLeaderboardResponseObject, error)
	// GetCurrentLeaderboard This week's leaderboard (live)
	// (GET /leaderboard/current)
	GetCurrentLeaderboard(ctx context.Context, request GetCurrentLeaderboardRequestObject) (GetCurrentLeaderboardResponseObject, error)
	// GetLeaderboard A weekly season's leaderboard
	// (GET /leaderboard/{seasonId})
	GetLeaderboard(ctx context.Context, request GetLeaderboardRequestObject) (GetLeaderboardResponseObject, error)
	// GetLiveTicket A ticket to open the live events socket
	// (POST /live/ticket)
	GetLiveTicket(ctx context.Context, request GetLiveTicketRequestObject) (GetLiveTicketResponseObject, error)
	// GetMe The signed-in player's profile
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// SetPublicName Choose the name other players see
	// (PUT /me/name)
	SetPublicName(ctx context.Context, request SetPublicNameRequestObject) (SetPublicNameResponseObject, error)
	// SetNotifications Choose which push notifications you get
	// (PUT /me/notifications)
	SetNotifications(ctx context.Context, request SetNotificationsRequestObject) (SetNotificationsResponseObject, error)
	// SetShowcase Choose the cards on your profile
	// (PUT /me/showcase)
	SetShowcase(ctx context.Context, request SetShowcaseRequestObject) (SetShowcaseResponseObject, error)
	// CompleteTutorial Mark the first-time tutorial as finished (or skipped)
	// (POST /me/tutorial)
	CompleteTutorial(ctx context.Context, request CompleteTutorialRequestObject) (CompleteTutorialResponseObject, error)
	// MergeCards Merge two of your cards
	// (POST /merges)
	MergeCards(ctx context.Context, request MergeCardsRequestObject) (MergeCardsResponseObject, error)
	// ClaimDailyPack Open today's free pack (one per UTC day)
	// (POST /packs/daily/claim)
	ClaimDailyPack(ctx context.Context, request ClaimDailyPackRequestObject) (ClaimDailyPackResponseObject, error)
	// GetPushKey The server's public VAPID key for web push subscriptions
	// (GET /push/key)
	GetPushKey(ctx context.Context, request GetPushKeyRequestObject) (GetPushKeyResponseObject, error)
	// UnsubscribePush Stop notifications on this browser
	// (DELETE /push/subscriptions)
	UnsubscribePush(ctx context.Context, request UnsubscribePushRequestObject) (UnsubscribePushResponseObject, error)
	// SubscribePush Get "your pack is ready" notifications on this browser
	// (POST /push/subscriptions)
	SubscribePush(ctx context.Context, request SubscribePushRequestObject) (SubscribePushResponseObject, error)
	// ListRecipes Recipes the signed-in player has discovered
	// (GET /recipes)
	ListRecipes(ctx context.Context, request ListRecipesRequestObject) (ListRecipesResponseObject, error)
	// GetRules The game rules players see
	// (GET /rules)
	GetRules(ctx context.Context, request GetRulesRequestObject) (GetRulesResponseObject, error)
	// ListTournaments Tournaments
	// (GET /tournaments)
	ListTournaments(ctx context.Context, request ListTournamentsRequestObject) (ListTournamentsResponseObject, error)
	// GetTournament A tournament, your entry and its results
	// (GET /tournaments/{tournamentId})
	GetTournament(ctx context.Context, request GetTournamentRequestObject) (GetTournamentResponseObject, error)
	// WithdrawFromTournament Withdraw your entry
	// (DELETE /tournaments/{tournamentId}/entry)
	WithdrawFromTournament(ctx context.Context, request WithdrawFromTournamentRequestObject) (WithdrawFromTournamentResponseObject, error)
	// EnterTournament Enter or change your lineup
	// (PUT /tournaments/{tournamentId}/entry)
	EnterTournament(ctx context.Context, request EnterTournamentRequestObject) (EnterTournamentResponseObject, error)
	// PreviewTournamentLineup Score a lineup without entering
	// (POST /tournaments/{tournamentId}/preview)
	PreviewTournamentLineup(ctx context.Context, request PreviewTournamentLineupRequestObject) (PreviewTournamentLineupResponseObject, error)
	// ListTrades Your trade offers
	// (GET /trades)
	ListTrades(ctx context.Context, request ListTradesRequestObject) (ListTradesResponseObject, error)
	// CreateTrade Send a trade offer
	// (POST /trades)
	CreateTrade(ctx context.Context, request CreateTradeRequestObject) (CreateTradeResponseObject, error)
	// AcceptTrade Accept an offer sent to you
	// (POST /trades/{tradeId}/accept)
	AcceptTrade(ctx context.Context, request AcceptTradeRequestObject) (AcceptTradeResponseObject, error)
	// CancelTrade Withdraw an offer you sent
	// (POST /trades/{tradeId}/cancel)
	CancelTrade(ctx context.Context, request CancelTradeRequestObject) (CancelTradeResponseObject, error)
	// DeclineTrade Decline an offer sent to you
	// (POST /trades/{tradeId}/decline)
	DeclineTrade(ctx context.Context, request DeclineTradeRequestObject) (DeclineTradeResponseObject, error)
	// GetProfile A player's profile
	// (GET /users/{username})
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// ListPlayerCards Another player's cards (to pick what to ask for in a trade)
	// (GET /users/{username}/cards)
	ListPlayerCards(ctx context.Context, request ListPlayerCardsRequestObject) (ListPlayerCardsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetAuthConfig operation middleware
func (sh *strictHandler) GetAuthConfig(w http.ResponseWriter, r *http.Request) {
	var request GetAuthConfigRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetAuthConfig(ctx, request.(GetAuthConfigRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetAuthConfig")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetAuthConfigResponseObject); ok {
		if err := validResponse.VisitGetAuthConfigResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

